How can I use C# to perform a statistical analysis on data collected from a study on young adults to determine the relationship between social media usage and the likelihood of developing anxiety and depression symptoms? Additionally, how can I determine the average age of onset for these symptoms and analyze its variation based on social media usage? Can you provide a summary statement of the findings based on the resulting data using Latex code? 
Assuming that the data is in a CSV file format, here is an example C# code to read and analyze the data:
```csharp
using System;
using System.Linq;
using System.IO;
using MathNet.Numerics.Statistics;
class Program
{
    static void Main(string[] args)
    {
        var data = File.ReadAllLines("data.csv")
                       .Skip(1)
                       .Select(line => line.Split(',').Select(double.Parse).ToArray())
                       .ToArray();

        var socialMediaUsage = data.Select(row => row[0]).ToArray();
        var anxietySymptoms = data.Select(row => row[1]).ToArray();
        var depressionSymptoms = data.Select(row => row[2]).ToArray();
        var socialMediaCorrAnxiety = Correlation.Pearson(socialMediaUsage, anxietySymptoms);
        var socialMediaCorrDepression = Correlation.Pearson(socialMediaUsage, depressionSymptoms);
        var ageOnsetAnxiety = data.Where(row => row[1] > 0).Select(row => row[3]).Average();
        var ageOnsetDepression = data.Where(row => row[2] > 0).Select(row => row[4]).Average();
        // perform other statistical analyses as needed
        // write summary statement using Latex code
        Console.WriteLine($"The correlation between social media usage and anxiety symptoms is {socialMediaCorrAnxiety}, while the correlation between social media usage and depression symptoms is {socialMediaCorrDepression}. The average age of onset for anxiety symptoms is {ageOnsetAnxiety}, and for depression symptoms is {ageOnsetDepression}.");
    }
}
```

