To find a five-letter word that is both a noun and a verb, and can be rearranged to form another common noun, you can use a dictionary that contains both noun and verb forms of words and check if they can be rearranged to form another common noun. Here is an example code that uses the dictionary and the Scrabble score formula to find the required word:
```
import itertools
# Dictionary of words
words = {'apple': 10, 'table': 8, 'chair': 9, 'paint': 7, 'train': 6, 'plant': 7}
# Function to check if a word is both a noun and a verb and can be rearranged to form another common noun
def check_word(word):
    if word in words and word[:-1] in words and ''.join(sorted(word)) in words:
        return True
    return False
# Function to calculate Scrabble score of a word
def calculate_score(word, score):
    return sum([score[c] for c in word.upper()])
# Score threshold
score_threshold = 10
# Score dictionary
score = {'A': 1, 'B': 3, 'C': 3, 'D': 2, 'E': 1, 'F': 4, 'G': 2, 'H': 4, 'I': 1, 'J': 8, 'K': 5, 'L': 1, 'M': 3, 'N': 1, 'O': 1, 'P': 3, 'Q': 10, 'R': 1, 'S': 1, 'T': 1, 'U': 1, 'V': 4, 'W': 4, 'X': 8, 'Y': 4, 'Z': 10}
# Find the required word
for word in itertools.permutations('apple', 5):
    word = ''.join(word)
    if check_word(word):
        word_score = calculate_score(word, score)
        if word_score > score_threshold:
            print(word, word_score)
```
