func validateInput(location: String, timeOfDay: String, behavior: String) -> Bool {
    let locationRegex = #"^[a-zA-Z]+(?:[\s-][a-zA-Z]+)*$"# // regular expression to validate location
    let timeOfDayRegex = #"^(0?[1-9]|1[0-2]):[0-5][0-9]\s(am|pm)$"# // regular expression to validate time of day
