using System;
using System.IO;
namespace BlogPost
{
    class Program
    {
        static void Main(string[] args)
        {
            string header = "My Favorite Travel Destination: Italy";
            string text = "Italy is known for its amazing cuisine, and I was lucky enough to indulge in some delicious pizzas during my trip. The pizza in Italy is unlike anything I've ever tasted before – the fresh ingredients and thin, crispy crust make for the perfect combination. I also enjoyed some amazing pastas, gelato, and wines during my visit.";
