How can I create a challenging flag guessing game using Swift? The game should display a flag from a randomly selected country and provide a list of possible countries for the user to guess from. However, each country will have a code name instead of its actual name. The user must correctly match the code name to the correct country flag. Here is a sample code to get started:
import UIKit
class ViewController: UIViewController {
    @IBOutlet weak var flagImageView: UIImageView!
    @IBOutlet weak var countryPicker: UIPickerView!

    let flags = ["🇺🇸", "🇯🇵", "🇫🇷", "🇩🇪", "🇨🇳", "🇧🇷"]
    let countries = ["United States", "Japan", "France", "Germany", "China", "Brazil"]

    var currentFlagIndex = 0
    var currentCountryIndex = 0

    override func viewDidLoad() {
        super.viewDidLoad()

        flagImageView.image = UIImage(named: flags[currentFlagIndex])
        countryPicker.dataSource = self
        countryPicker.delegate = self
    }
    @IBAction func checkAnswer(_ sender: UIButton) {
        let selectedCountry = countries[currentCountryIndex]

        if selectedCountry == "United States" && currentFlagIndex == 0 {
            showAlert(title: "Correct!", message: "You guessed the flag belongs to United States.")
        } else if selectedCountry == "Japan" && currentFlagIndex == 1 {
            showAlert(title: "Correct!", message: "You guessed the flag belongs to Japan.")
        } else if selectedCountry == "France" && currentFlagIndex == 2 {
            showAlert(title: "Correct!", message: "You guessed the flag belongs to France.")
        } else if selectedCountry == "Germany" && currentFlagIndex == 3 {
            showAlert(title: "Correct!", message: "You guessed the flag belongs to Germany.")
        } else if selectedCountry == "China" && currentFlagIndex == 4 {
            showAlert(title: "Correct!", message: "You guessed the flag belongs to China.")
        } else if selectedCountry == "Brazil" && currentFlagIndex == 5 {
            showAlert(title: "Correct!", message: "You guessed the flag belongs to Brazil.")
        } else {
            showAlert(title: "Sorry", message: "Your guess was incorrect. The flag belongs to \(countries[currentFlagIndex]).")
        }
    }

    func showAlert(title: String, message: String) {
        let alert = UIAlertController(title: title, message: message, preferredStyle: .alert)
        let okAction = UIAlertAction(title: "OK", style: .default, handler: nil)
        alert.addAction(okAction)
        present(alert, animated: true, completion: nil)
    }
}
extension ViewController: UIPickerViewDataSource, UIPickerViewDelegate {
    func numberOfComponents(in pickerView: UIPickerView) -> Int {
        return 1
    }

    func pickerView(_ pickerView: UIPickerView, numberOfRowsInComponent component: Int) -> Int {
        return countries.count
    }

    func pickerView(_ pickerView: UIPickerView, titleForRow row: Int, forComponent component: Int) -> String? {
        return countries[row]
    }

    func pickerView(_ pickerView: UIPickerView, didSelectRow row: Int, inComponent component: Int) {
        currentCountryIndex = row
    }
} 
