```
import math
class Polygon:
    def __init__(self, sides, length):
        self.sides = sides
        self.length = length

    def perimeter(self):
        return self.sides * self.length

    def area(self):
        raise NotImplementedError("Subclass must implement abstract method")

class Triangle(Polygon):
    def __init__(self, base, height):
        super().__init__(sides=3, length=base)
        self.height = height

    def area(self):
        return 0.5 * self.base * self.height

class Square(Polygon):
    def __init__(self, side):
        super().__init__(sides=4, length=side)

    def area(self):
        return self.length ** 2

class Pentagon(Polygon):
    def __init__(self, side):
        super().__init__(sides=5, length=side)

    def area(self):
        return 0.25 * math.sqrt(5 * (5 + 2 * math.sqrt(5))) * self.length ** 2

class Hexagon(Polygon):
    def __init__(self, side):
        super().__init__(sides=6, length=side)

    def area(self):
        return 1.5 * math.sqrt(3) * self.length ** 2

class Heptagon(Polygon):
    def __init__(self, side):
        super().__init__(sides=7, length=side)

    def area(self):
        return 0.25 * self.sides * self.length ** 2 * math.cot(math.pi / self.sides)

class Octagon(Polygon):
    def __init__(self, side):
        super().__init__(sides=8, length=side)

    def area(self):
        return 2 * (1 + math.sqrt(2)) * self.length ** 2
shapes = [Triangle(6, 4), Square(5), Pentagon(3), Hexagon(7), Heptagon(2), Octagon(9)]
largest_area = 0
for shape in shapes:
    area = shape.area()
    if area > largest_area:
        largest_area = area
        largest_shape = shape.__class__.__name__
print(f"The shape with the largest area is {largest_shape} with an area of {largest_area}.")
```
