vector<int> shortestPath(int start, int end, vector<RoadSegment> roads) {
    // Initialize distances and visited nodes
    vector<int> dist(roads.size(), INT_MAX);
    vector<bool> visited(roads.size(), false);
    dist[start] = 0;
    // Loop through all nodes
    for (int i = 0; i < roads.size(); i++) {
        // Find the node with the smallest distance that has not been visited
        int minDist = INT_MAX;
        int minIndex = -1;
        for (int j = 0; j < roads.size(); j++) {
            if (!visited[j] && dist[j] < minDist) {
                minDist = dist[j];
                minIndex = j;
            }
        }
        // Mark the node as visited
        visited[minIndex] = true;
        // Update the distances of all adjacent nodes
        for (int j = 0; j < roads.size(); j++) {
            if (roads[j].start == minIndex && !visited[roads[j].end]) {
                dist[roads[j].end] = min(dist[roads[j].end], dist[minIndex] + roads[j].length);
            }
            if (roads[j].end == minIndex && !visited[roads[j].start]) {
                dist[roads[j].start] = min(dist[roads[j].start], dist[minIndex] + roads[j].length);
            }
        }
    }
    // Build the shortest path vector
    vector<int> path;
    int curr = end;
    while (curr != start) {
        path.push_back(curr);
        for (int i = 0; i < roads.size(); i++) {
            if (roads[i].start == curr && dist[roads[i].end] + roads[i].length == dist[curr]) {
                curr = roads[i].end;
                break;
            }
            if (roads[i].end == curr && dist[roads[i].start] + roads[i].length == dist[curr]) {
                curr = roads[i].start;
                break;
            }
        }
    }
    path.push_back(start);
    reverse(path.begin(), path.end());
    return path;
}
