    val path = findPath(start, target, List.empty[(Int, Int)])
    if (path.nonEmpty) {
      println(s"Path found: $path")
      println(s"Total moves: ${path.length - 1}")
    } else {
      println("No path found.")
    }
  }
  def findPath(current: (Int, Int), target: (Int, Int), visited: List[(Int, Int)]): List[(Int, Int)] = {
    if (current == target) {
      visited :+ current
    } else {
      val nextMoves = getNextMoves(current, visited)
      val possiblePaths = nextMoves.map(move => findPath(move, target, visited :+ current))
      possiblePaths.filter(_.nonEmpty).minByOption(_.length).getOrElse(List.empty)
    }
  }
  def getNextMoves(current: (Int, Int), visited: List[(Int, Int)]): List[(Int, Int)] = {
    val (x, y) = current
    List(
