      (x + 2, y - 1),
      (x - 2, y + 1),
      (x - 2, y - 1),
      (x + 1, y + 2),
      (x + 1, y - 2),
      (x - 1, y + 2),
      (x - 1, y - 2)
    ).filter(move => move._1 >= 1 && move._1 <= 8 && move._2 >= 1 && move._2 <= 8 && !visited.contains(move))
  }
}
