2. XLM-RoBERTa (Cross-lingual Language Model - RoBERTa)
```
import org.apache.commons.io.IOUtils;
import org.json.JSONObject;
import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.factory.Nd4j;
import org.nd4j.linalg.io.ClassPathResource;
import org.nd4j.linalg.ops.transforms.Transforms;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
public class XLMRoberta {
    private static final Logger log = LoggerFactory.getLogger(XLMRoberta.class);
    private final Tokenizer tokenizer;
    private final INDArray meanEmbedding;
    public XLMRoberta() throws IOException {
        tokenizer = new Tokenizer();
        meanEmbedding = loadMeanEmbedding();
    }
    public List<String> predict(String text) throws IOException {
        List<String> tokens = tokenizer.tokenize(text);
        INDArray input = tokenizer.encode(tokens);
        INDArray output = input.mmul(meanEmbedding);
        output = Transforms.sigmoid(output);
        List<String> labels = new ArrayList<>();
        if (output.getDouble(0) > 0.5) {
            labels.add("positive");
        }
        if (output.getDouble(1) > 0.5) {
            labels.add("negative");
        }
        return labels;
    }
    private INDArray loadMeanEmbedding() throws IOException {
        String json = IOUtils.toString(new ClassPathResource("xlm-roberta.json").getInputStream(), StandardCharsets.UTF_8);
        JSONObject obj = new JSONObject(json);
        return Nd4j.create(obj.getJSONArray("mean_embedding").toList());
    }
}
```
