val giftCardAmount = 50.00
val salesTaxRate = 0.07
val freeShippingThreshold = 25.00
// Define a function to calculate the total cost of an order
def calculateOrderCost(itemCount: Int, itemPrice: Double): Double = {
  val subtotal = itemCount * itemPrice
  val salesTax = subtotal * salesTaxRate
  val shipping = if (subtotal >= freeShippingThreshold) 0 else 5.00
  subtotal + salesTax + shipping
}
// Define a function to find the minimum number of items needed to maximize the gift card value
def findOptimalItemCount(itemPrice: Double): Int = {
  var itemCount = 1
  var maxItemCount = 1
  var maxGiftCardValue = 0.00
  while (calculateOrderCost(itemCount, itemPrice) <= giftCardAmount) {
    val giftCardValue = giftCardAmount - calculateOrderCost(itemCount, itemPrice)
    if (giftCardValue > maxGiftCardValue) {
      maxGiftCardValue = giftCardValue
      maxItemCount = itemCount
    }
    itemCount += 1
  }
  maxItemCount
}
// Example usage: find the optimal item count for an item priced at $10.00
val optimalItemCount = findOptimalItemCount(10.00)
println(s"Add $optimalItemCount items to your cart to maximize the value of your gift card.")
