      case Empty => Node(value, Empty, Empty, new ReentrantReadWriteLock())
      case Node(v, l, r, lock) if value < v =>
        lock.writeLock().lock()
        val updatedL = insert(l, value)
        Node(v, updatedL, r, lock)
      case Node(v, l, r, lock) if value > v =>
        lock.writeLock().lock()
        val updatedR = insert(r, value)
        Node(v, l, updatedR, lock)
      case _ => tree
    }
  }
  def search(tree: BST, value: Int): Boolean = {
    tree match {
      case Empty => false
      case Node(v, l, r, _) if value < v => search(l, value)
      case Node(v, l, r, _) if value > v => search(r, value)
      case _ => true
