Here's a C# code that can help you sort the list of fruits based on their sweetness level and display their corresponding sugar content in grams per 100 grams:
```csharp
using System;
using System.Collections.Generic;
class Fruit
{
    public string Name { get; set; }
    public int Sweetness { get; set; }
    public double SugarContent { get; set; }
}
class Program
{
    static void Main(string[] args)
    {
        List<Fruit> fruits = new List<Fruit>();
        // Add fruits to the list with their sweetness level and sugar content
        fruits.Add(new Fruit { Name = "Apple", Sweetness = 7, SugarContent = 10.4 });
        fruits.Add(new Fruit { Name = "Kiwi", Sweetness = 5, SugarContent = 8.3 });
        fruits.Add(new Fruit { Name = "Strawberry", Sweetness = 9, SugarContent = 5.4 });
        // Sort fruits based on their sweetness level
        fruits.Sort((x, y) => x.Sweetness.CompareTo(y.Sweetness));
        // Display the sorted list with their sugar content in grams per 100 grams
        Console.WriteLine("Fruit\t\tSweetness\tSugar content (g/100g)");
        foreach (Fruit fruit in fruits)
        {
            Console.WriteLine("{0}\t\t{1}\t\t{2}", fruit.Name, fruit.Sweetness, fruit.SugarContent);
        }
        // Determine the sweetest fruit
        Fruit sweetestFruit = fruits[fruits.Count - 1];
        Console.WriteLine("The sweetest fruit is {0} with a sweetness level of {1} and sugar content of {2} g/100g.", sweetestFruit.Name, sweetestFruit.Sweetness, sweetestFruit.SugarContent);
    }
}
```
